            'const script = [',
            '  { type: "tool_call", name: "check_slot" },',
            '  { type: "tool_call", name: "check_slot" },',
            '  { type: "tool_call", name: "check_slot" },',
            '  { type: "final", text: "Booked." },',
            '];',
            'const MAX_STEPS = 3;',
